(function(Scratch) {
    'use strict';

    if (!Scratch.extensions.unsandboxed) {
        throw new Error('NovaAI requires an unsandboxed extension.');
    }

    class NovaAI {
        constructor() {
            this.lastResponse = '';
        }

        getInfo() {
            return {
                id: 'novaaiextension',
                name: 'NovaAI',
                color1: '#5865F2',
                color2: '#4752C4',
                color3: '#3C45A5',

                blockIconURI: 'data:image/png;base64,',

                blocks: [
                    {
                        opcode: 'ask',
                        blockType: Scratch.BlockType.REPORTER,
                        text: 'ask NovaAI [PROMPT]',
                        arguments: {
                            PROMPT: {
                                type: Scratch.ArgumentType.STRING,
                                defaultValue: 'Hello!'
                            }
                        }
                    },
                    {
                        opcode: 'lastResponse',
                        blockType: Scratch.BlockType.REPORTER,
                        text: 'NovaAI last response'
                    },
                    {
                        opcode: 'currentVersion',
                        blockType: Scratch.BlockType.REPORTER,
                        text: 'current version'
                    }
                ]
            };
        }

        async ask(args) {
            const prompt = String(args.PROMPT);

            try {
                const url =
                    'https://novabotapi.enzonic.dev/' +
                    encodeURIComponent(prompt);

                const response = await fetch(url);

                if (!response.ok) {
                    const errorText = await response.text().catch(() => '');
                    const suffix = errorText ? ': ' + errorText : '';

                    this.lastResponse =
                        'NovaAI API error: HTTP ' +
                        response.status +
                        suffix;

                    return this.lastResponse;
                }

                const text = await response.text();

                this.lastResponse = text;
                return text;

            } catch (error) {
                this.lastResponse =
                    'NovaAI connection error: ' + error.message;

                return this.lastResponse;
            }
        }

        async askAndWait(args) {
            return await this.ask(args);
        }

        getLastResponse() {
            return this.lastResponse;
        }

        currentVersion() {
            return '0.5.0';
        }
    }

    Scratch.extensions.register(new NovaAI());
})(Scratch);
